const body = $input.first().json.body;
const profiles = Array.isArray(body) ? body : body?.mutual_connections;
const target = Array.isArray(body) ? {} : (body?.target || {});
const context = Array.isArray(body) ? {} : { owner_user_id: body?.owner_user_id, workflow_run_id: body?.workflow_run_id, search_request_id: body?.search_request_id, search_hash: body?.search_hash };

if (!Array.isArray(profiles)) {
	throw new Error("Expected webhook body to contain mutual_connections array.");
}

const targetCompany = target.company || target.current_company || "";
const targetSchool = Array.isArray(target.education) && target.education[0]
	? target.education[0].school || ""
	: "";

return profiles.map((profile, index) => ({
	json: {
		profile_id: index + 1,
		...context,
		target,
		target_name: target.name || "",
		company: profile.company || targetCompany,
		college: profile.college || targetSchool,
		...profile,
	},
}));

function toNumber(value) {
	if (!value) return 0;

	const text = String(value).trim();

	if (text.includes("500+")) return 500;

	const number = text.replace(/[^\d]/g, "");

	return number ? Number(number) : 0;
}

return $input.all().map(item => {

	const p = item.json;

	return {
		json: {

			...p,

			name: (p.name || "").trim(),

			headline: (p.headline || "").trim(),

			location: (p.location || "").trim(),

			about: (p.about || "").trim(),

			current_company: (p.current_company || "").trim(),

			position: (p.position || "").trim(),

			company: (p.company || "").trim(),

			college: (p.college || "").trim(),

			followers: toNumber(p.followers),

			connections: toNumber(p.connections),

			experience: Array.isArray(p.experience)
				? p.experience
				: [],

			education: Array.isArray(p.education)
				? p.education
				: [],

			skills: Array.isArray(p.skills)
				? p.skills
				: []

		}
	};

});

const TECH_KEYWORDS = [
	"javascript",
	"typescript",
	"react",
	"angular",
	"vue",
	"node",
	"python",
	"java",
	"c#",
	".net",
	"aws",
	"azure",
	"gcp",
	"docker",
	"kubernetes",
	"sql",
	"mongodb",
	"postgresql"
];

return $input.all().map(item => {

	const p = item.json;

	const text = [
		p.headline,
		p.about,
		...(p.skills || [])
	]
	.join(" ")
	.toLowerCase();

	const detectedSkills = TECH_KEYWORDS.filter(skill =>
		text.includes(skill)
	);

	return {
		json: {

			...p,

			text,

			detected_skills: detectedSkills,

			experience_count: p.experience.length,

			education_count: p.education.length,

			skill_count: p.skills.length,

			has_about: p.about.length > 0,

			has_location: p.location.length > 0,

			has_company: p.current_company.length > 0

		}
	};

});

/**
 * ==========================================================
 * Warm Path Finder
 * Seniority Engine v2
 * ----------------------------------------------------------
 * Purpose:
 * Determine professional seniority using:
 * - Role
 * - Headline
 * - Position
 *
 * Outputs:
 * seniority
 * seniority_score
 * confidence
 * classification_reason
 * ==========================================================
 */

function contains(text, keywords) {
	return keywords.some(keyword => text.includes(keyword));
}

return $input.all().map(item => {

	const role = (item.json.role || "Other").toLowerCase();

	const text = [
		item.json.headline || "",
		item.json.position || ""
	]
	.join(" ")
	.toLowerCase();

	let seniority = "Mid";
	let seniority_score = 40;
	let confidence = 0.60;
	let classification_reason = "Default classification";

	/* ======================================================
	   UNIVERSAL
	====================================================== */

	if (contains(text, ["intern", "internship", "trainee"])) {
		seniority = "Intern";
		seniority_score = 10;
		confidence = 0.99;
		classification_reason = "Intern keyword detected";
	}

	else if (contains(text, ["junior", "jr."])) {
		seniority = "Junior";
		seniority_score = 20;
		confidence = 0.98;
		classification_reason = "Junior keyword detected";
	}

	/* ======================================================
	   ENGINEERING
	====================================================== */

	else if (role === "engineering") {

		if (contains(text, ["principal engineer", "staff engineer"])) {
			seniority = "Lead";
			seniority_score = 75;
			confidence = 0.95;
			classification_reason = "Principal/Staff Engineer";
		}

		else if (contains(text, [
			"technical lead",
			"tech lead",
			"team lead",
			"lead engineer",
			"lead developer"
		])) {
			seniority = "Lead";
			seniority_score = 70;
			confidence = 0.98;
			classification_reason = "Engineering Lead";
		}

		else if (contains(text, [
			"engineering manager",
			"development manager"
		])) {
			seniority = "Manager";
			seniority_score = 80;
			confidence = 0.98;
			classification_reason = "Engineering Manager";
		}

		else if (contains(text, [
			"senior software engineer",
			"senior developer",
			"senior engineer",
			"sr."
		])) {
			seniority = "Senior";
			seniority_score = 60;
			confidence = 0.95;
			classification_reason = "Senior Engineer";
		}

		else {
			seniority = "Mid";
			seniority_score = 40;
			confidence = 0.85;
			classification_reason = "Engineering default";
		}

	}

	/* ======================================================
	   HR
	====================================================== */

	else if (role === "hr") {

		if (contains(text, [
			"director",
			"head of hr",
			"head of people"
		])) {
			seniority = "Director";
			seniority_score = 90;
			confidence = 0.98;
			classification_reason = "HR Director";
		}

		else if (contains(text, [
			"hr manager",
			"human resources manager",
			"people manager",
			"talent manager"
		])) {
			seniority = "Manager";
			seniority_score = 80;
			confidence = 0.97;
			classification_reason = "HR Manager";
		}

		else if (contains(text, [
			"executive",
			"specialist",
			"generalist",
			"recruiter",
			"talent acquisition"
		])) {
			seniority = "Mid";
			seniority_score = 40;
			confidence = 0.92;
			classification_reason = "HR Professional";
		}

		else {
			seniority = "Mid";
			seniority_score = 40;
			confidence = 0.75;
			classification_reason = "HR default";
		}

	}

	/* ======================================================
	   QA
	====================================================== */

	else if (role === "qa") {

		if (contains(text, [
			"qa manager",
			"test manager"
		])) {
			seniority = "Manager";
			seniority_score = 80;
			confidence = 0.97;
			classification_reason = "QA Manager";
		}

		else if (contains(text, [
			"lead qa",
			"qa lead",
			"test lead"
		])) {
			seniority = "Lead";
			seniority_score = 70;
			confidence = 0.97;
			classification_reason = "QA Lead";
		}

		else if (contains(text, [
			"senior qa",
			"senior test engineer"
		])) {
			seniority = "Senior";
			seniority_score = 60;
			confidence = 0.96;
			classification_reason = "Senior QA";
		}

		else {
			seniority = "Mid";
			seniority_score = 40;
			confidence = 0.85;
			classification_reason = "QA default";
		}

	}

	/* ======================================================
	   BUSINESS DEVELOPMENT
	====================================================== */

	else if (role === "business development") {

		if (contains(text, [
			"director",
			"head of sales",
			"head of business"
		])) {
			seniority = "Director";
			seniority_score = 90;
			confidence = 0.98;
			classification_reason = "Business Director";
		}

		else if (contains(text, [
			"manager",
			"sales manager"
		])) {
			seniority = "Manager";
			seniority_score = 80;
			confidence = 0.97;
			classification_reason = "Business Manager";
		}

		else {
			seniority = "Mid";
			seniority_score = 40;
			confidence = 0.85;
			classification_reason = "Business default";
		}

	}

	/* ======================================================
	   EXECUTIVE
	====================================================== */

	else if (role === "executive") {

		if (contains(text, [
			"founder",
			"co-founder"
		])) {
			seniority = "Founder";
			seniority_score = 100;
			confidence = 1.00;
			classification_reason = "Founder";
		}

		else if (contains(text, [
			"ceo",
			"cto",
			"coo",
			"chief"
		])) {
			seniority = "Executive";
			seniority_score = 95;
			confidence = 0.99;
			classification_reason = "C-Level Executive";
		}

		else if (contains(text, [
			"director",
			"vice president",
			"vp"
		])) {
			seniority = "Director";
			seniority_score = 90;
			confidence = 0.98;
			classification_reason = "Director/VP";
		}

		else {
			seniority = "Executive";
			seniority_score = 90;
			confidence = 0.90;
			classification_reason = "Executive default";
		}

	}

	return {
		json: {
			...item.json,

			seniority,
			seniority_score,

			confidence,

			classification_reason
		}
	};

});

