return $input.all().map(item => {
    const p = item.json;

    const decisionPower = p.analysis.decision_power || "Low";
    const seniority = p.analysis.seniority || "Junior";
    const companyMatch = p.target_company === p.profile.current_company;

    const relationshipStrength = companyMatch ? 85 : 45;

    const credibility =
        seniority === "Executive" || seniority === "Founder"
            ? 95
            : seniority === "Lead"
            ? 85
            : seniority === "Mid"
            ? 75
            : 60;

    const likelihood =
        decisionPower === "Very High"
            ? 90
            : decisionPower === "High"
            ? 80
            : decisionPower === "Medium"
            ? 65
            : 50;

    const introductionQuality = Math.round(
        (relationshipStrength + credibility + likelihood) / 3
    );

    const recommendation =
        introductionQuality >= 85
            ? "Strong"
            : introductionQuality >= 70
            ? "Moderate"
            : "Weak";

    return {
        json: {
            ...p,

            ai_analysis: {
                relationship_strength: {
                    score: relationshipStrength,
                    level:
                        relationshipStrength >= 80
                            ? "Strong"
                            : relationshipStrength >= 60
                            ? "Medium"
                            : "Weak"
                },

                credibility: {
                    score: credibility,
                    level:
                        credibility >= 85
                            ? "High"
                            : credibility >= 70
                            ? "Medium"
                            : "Low"
                },

                company_alignment: {
                    score: companyMatch ? 100 : 40,
                    reason: companyMatch
                        ? "Currently works at the target company."
                        : "Works outside the target company."
                },

                industry_alignment: {
                    score: 80,
                    reason: "Estimated from the detected role and experience."
                },

                likelihood_of_reply: {
                    score: likelihood,
                    reason:
                        "Estimated using seniority, decision power and profile quality."
                },

                introduction_quality: {
                    score: introductionQuality,
                    reason:
                        "Estimated from relationship strength, credibility and likelihood of reply."
                },

                overall_recommendation: recommendation,

                explanation:
                    "Temporary mock AI analysis generated from the rule-engine outputs.",

                personalized_introduction:
                    "Hi " + p.profile.name + ", I came across your profile while exploring professionals at " + p.target_company + ". I was impressed by your background and would love to connect and learn more about your experience."
            }
        }
    };
});

return $input.all().map(item => {
    const p = item.json;

    const ai = p.ai_analysis;

    const relationship = ai.relationship_strength.score;
    const credibility = ai.credibility.score;
    const company = ai.company_alignment.score;
    const industry = ai.industry_alignment.score;
    const reply = ai.likelihood_of_reply.score;
    const intro = ai.introduction_quality.score;

    const finalScore = Math.round(
        relationship * 0.20 +
        credibility * 0.20 +
        company * 0.20 +
        industry * 0.15 +
        reply * 0.15 +
        intro * 0.10
    );

    let finalGrade;

    if (finalScore >= 90)
        finalGrade = "A+";
    else if (finalScore >= 80)
        finalGrade = "A";
    else if (finalScore >= 70)
        finalGrade = "B";
    else if (finalScore >= 60)
        finalGrade = "C";
    else if (finalScore >= 50)
        finalGrade = "D";
    else
        finalGrade = "F";

    return {
        json: {
            ...p,

            final_score: finalScore,
            final_grade: finalGrade
        }
    };
});

